<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    HostName</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 114.115.116.117</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # 真实 IP 或域名</span></span>
